import os
import random
import struct
from typing import List

# Target: arbitrary binary buffer used by endian get/put helpers and SDP parsers.
# Strategy:
# - Randomly choose one of several profiles that produce valid/interesting inputs:
#   1) Exact-size numeric fields (2/4/8 bytes) containing edge-case numbers
#      in little/big endian to exercise bt_get_* and bt_put_*.
#   2) Mixed-length buffers >= required minimums with aligned/un-aligned prefixes.
#   3) SDP-like fragments that can be plausibly parsed by sdp_uuid_extract,
#      sdp_extract_seqtype, sdp_extract_pdu/attr (simple valid TLVs and sequences).
# - Keep total length <= 4096.

EDGE_U16 = [0x0000, 0x0001, 0x00FF, 0x0100, 0x7FFF, 0x8000, 0xFFFF]
EDGE_U32 = [0x00000000, 0x00000001, 0x0000FFFF, 0x00FF00FF, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFF]
EDGE_U64 = [0, 1, 0xFFFFFFFF, 0x7FFFFFFFFFFFFFFF, 0x8000000000000000, 0xFFFFFFFFFFFFFFFF]

# Simple SDP encoding helpers (subset sufficient for parser acceptance):
# SDP DTD base: type in upper 5 bits, size index in lower 3 bits.
# We'll build DataElementSequence (type=6) with 8/16-bit length fields, and include
# a couple of UINT16/UINT32/UUID16/UUID128 elements.

def sdp_elem_header(t: int, size_bytes: bytes) -> bytes:
    # size descriptor depends on explicit length size
    l = len(size_bytes)
    if l == 1:
        dtd = (t << 3) | 5  # additional 8-bit size
    elif l == 2:
        dtd = (t << 3) | 6  # additional 16-bit size
    elif l == 4:
        dtd = (t << 3) | 7  # additional 32-bit size
    else:
        # small fixed sizes (1,2,4,8,16) for integers/uuids handled elsewhere
        dtd = (t << 3) | 5
    return bytes([dtd]) + size_bytes

def sdp_uint16(v: int) -> bytes:
    # type=1 (unsigned int), size index for 2-byte is 1
    dtd = (1 << 3) | 1
    return bytes([dtd]) + struct.pack('>H', v & 0xFFFF)

def sdp_uint32(v: int) -> bytes:
    dtd = (1 << 3) | 2
    return bytes([dtd]) + struct.pack('>I', v & 0xFFFFFFFF)

def sdp_uuid16(v: int) -> bytes:
    # type=3 (UUID), size index 1 => 2 bytes
    dtd = (3 << 3) | 1
    return bytes([dtd]) + struct.pack('>H', v & 0xFFFF)

def sdp_uuid128(data: bytes) -> bytes:
    dtd = (3 << 3) | 4  # 16-byte UUID
    if len(data) != 16:
        data = (data + b"\x00" * 16)[:16]
    return bytes([dtd]) + data

def sdp_string(bs: bytes) -> bytes:
    # type=4 (string) with 8-bit or 16-bit length depending size
    if len(bs) < 256:
        return sdp_elem_header(4, struct.pack('>B', len(bs))) + bs
    else:
        return sdp_elem_header(4, struct.pack('>H', len(bs))) + bs

def sdp_seq(elements: List[bytes]) -> bytes:
    payload = b''.join(elements)
    if len(payload) < 256:
        hdr = sdp_elem_header(6, struct.pack('>B', len(payload)))
    else:
        hdr = sdp_elem_header(6, struct.pack('>H', len(payload)))
    return hdr + payload

def build_plausible_sdp_record(rng: random.Random, max_len: int) -> bytes:
    # Build a small attribute list-like sequence: [ (attrId, value), ... ]
    elems = []
    # Common attributes: ServiceClassIDList (0x0001) as a sequence of UUIDs
    uuids = []
    for _ in range(rng.randint(1, 3)):
        if rng.random() < 0.5:
            uuids.append(sdp_uuid16(rng.choice([0x1101, 0x111E, 0x1124, 0x180F, 0x1812])))
        else:
            # random 128-bit UUID
            uuids.append(sdp_uuid128(rng.randbytes(16)))
    svc_list = sdp_seq(uuids)
    attr1 = sdp_uint16(0x0001) + svc_list
    elems.append(attr1)
    # ProtocolDescriptorList (0x0004): sequence of sequences
    l2cap = sdp_seq([sdp_uuid16(0x0100)])
    rfcomm_params = [sdp_uuid16(0x0003)]
    if rng.random() < 0.7:
        rfcomm_params.append(sdp_uint16(rng.randint(1, 30)))
    rfcomm = sdp_seq(rfcomm_params)
    pdl = sdp_seq([l2cap, rfcomm])
    attr4 = sdp_uint16(0x0004) + pdl
    elems.append(attr4)
    # Optional ServiceName (0x0100)
    if rng.random() < 0.8:
        name = ("Svc" + str(rng.randint(0, 9999))).encode('ascii')
        attr_name = sdp_uint16(0x0100) + sdp_string(name)
        elems.append(attr_name)
    seq = sdp_seq(elems)
    return seq[:max_len]

def pick_endian_numeric_profile(rng: random.Random) -> bytes:
    kind = rng.choice(['le16', 'be16', 'le32', 'be32', 'le64', 'be64'])
    if kind.endswith('16'):
        v = rng.choice(EDGE_U16 + [rng.getrandbits(16)])
        if kind.startswith('le'):
            return struct.pack('<H', v)
        else:
            return struct.pack('>H', v)
    elif kind.endswith('32'):
        v = rng.choice(EDGE_U32 + [rng.getrandbits(32)])
        if kind.startswith('le'):
            return struct.pack('<I', v)
        else:
            return struct.pack('>I', v)
    else:
        v = rng.choice(EDGE_U64 + [rng.getrandbits(64)])
        if kind.startswith('le'):
            return struct.pack('<Q', v)
        else:
            return struct.pack('>Q', v)

def mixed_buffer(rng: random.Random, min_len: int) -> bytes:
    # Prefix junk then an aligned numeric of varying size to exercise unaligned accesses
    prefix_len = rng.randint(0, 7)
    prefix = rng.randbytes(prefix_len)
    num = pick_endian_numeric_profile(rng)
    suffix_len = rng.randint(0, 32)
    suffix = rng.randbytes(suffix_len)
    buf = prefix + num + suffix
    if len(buf) < min_len:
        buf += b"\x00" * (min_len - len(buf))
    return buf[:4096]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    profile = rng.choices(
        population=['exact16', 'exact32', 'exact64', 'mixed_min2', 'mixed_min4', 'mixed_min8', 'sdp_small', 'sdp_medium'],
        weights=[10, 10, 10, 8, 8, 8, 23, 23],
        k=1
    )[0]

    if profile == 'exact16':
        return pick_endian_numeric_profile(rng) if rng.random() < 0.5 else struct.pack('<H', rng.choice(EDGE_U16))
    if profile == 'exact32':
        return pick_endian_numeric_profile(rng) if rng.random() < 0.5 else struct.pack('>I', rng.choice(EDGE_U32))
    if profile == 'exact64':
        return pick_endian_numeric_profile(rng) if rng.random() < 0.5 else struct.pack('<Q', rng.choice(EDGE_U64))
    if profile == 'mixed_min2':
        return mixed_buffer(rng, 2)
    if profile == 'mixed_min4':
        return mixed_buffer(rng, 4)
    if profile == 'mixed_min8':
        return mixed_buffer(rng, 8)
    if profile == 'sdp_small':
        # Construct a small plausible SDP sequence suitable for sdp_extract_seqtype and uuid_extract
        seq = build_plausible_sdp_record(rng, 128)
        return seq if seq else b"\x36\x00\x00"  # minimal empty sequence header
    if profile == 'sdp_medium':
        # Larger but bounded payload for sdp_extract_pdu/attr
        seq = build_plausible_sdp_record(rng, 512)
        return seq if seq else b"\x36\x00\x00"

    # Fallback
    return struct.pack('<Q', 0)
